practice.solution:
def bm25(docs, query, k1, b):
    import math
    def words(s):
        out = []
        cur = ''
        for ch in s.lower():
            if ch.isalpha() or ch.isdigit():
                cur += ch
            else:
                if cur:
                    out.append(cur)
                cur = ''
        if cur:
            out.append(cur)
        return out
    toks = [words(d) for d in docs]
    n_docs = len(docs)
    if n_docs == 0:
        return []
    avg = sum(len(t) for t in toks) / n_docs
    terms = []
    for w in words(query):
        if w not in terms:
            terms.append(w)
    scores = []
    for t in toks:
        s = 0.0
        for w in terms:
            n = 0
            for other in toks:
                if w in other:
                    n += 1
            f = t.count(w)
            if f == 0:
                continue
            idf = math.log(1 + (n_docs - n + 0.5) / (n + 0.5))
            s += idf * f * (k1 + 1) / (f + k1 * (1 - b + b * len(t) / avg))
        scores.append(round(s, 4))
    return scores

