practice.solution:
def eval_expr(expr, vars):
    class Undef(Exception):
        pass

    def val(tok):
        tok = tok.strip()
        conv = None
        if ' | ' in tok:
            tok, conv = tok.split(' | ', 1)
            tok = tok.strip()
            conv = conv.strip()
        if tok[:1] == '"' or tok[:1] == "'":
            v = tok[1:-1]
        elif tok == 'true':
            v = True
        elif tok == 'false':
            v = False
        else:
            try:
                v = float(tok) if '.' in tok else int(tok)
            except ValueError:
                if tok not in vars:
                    raise Undef()
                v = vars[tok]
        if conv in ('float', 'int'):
            if isinstance(v, str):
                keep = ''
                for ch in v:
                    if ch.isdigit() or ch in '.-':
                        keep += ch
                v = float(keep)
            else:
                v = float(v)
            if conv == 'int':
                v = int(v)
        return v

    def clause(c):
        c = c.strip()
        if c.endswith(' is not defined'):
            return c[:-15].strip() not in vars
        if c.endswith(' is defined'):
            return c[:-11].strip() in vars
        for op in ['==', '!=', '<=', '>=', '<', '>']:
            parts = c.split(' ' + op + ' ', 1)
            if len(parts) == 2:
                a = val(parts[0])
                b = val(parts[1])
                if op == '==':
                    return a == b
                if op == '!=':
                    return a != b
                if op == '<':
                    return a < b
                if op == '>':
                    return a > b
                if op == '<=':
                    return a <= b
                return a >= b
        return bool(val(c))

    try:
        for alt in expr.split(' or '):
            ok = True
            for c in alt.split(' and '):
                if not clause(c):
                    ok = False
                    break
            if ok:
                return True
        return False
    except Undef:
        return 'error'

