def critical_path(tasks):
    info = {}
    for name, days, deps in tasks:
        info[name] = [days, deps]
    fin = {}

    def finish(n):
        if n in fin:
            return fin[n]
        days, deps = info[n]
        best = 0
        for d in deps:
            best = max(best, finish(d))
        fin[n] = days + best
        return fin[n]

    for n in info:
        finish(n)
    if not info:
        return [0, []]
    end = sorted(info, key=lambda n: [-fin[n], n])[0]
    path = [end]
    cur = end
    while info[cur][1]:
        deps = info[cur][1]
        cur = sorted(deps, key=lambda n: [-fin[n], n])[0]
        path.append(cur)
    path.reverse()
    return [fin[end], path]

