practice.solution:
def lisp_eval(src, fuel):
    toks = src.replace('(', ' ( ').replace(')', ' ) ').split()
    pos = [0]

    def parse():
        t = toks[pos[0]]
        pos[0] += 1
        if t == '(':
            out = []
            while toks[pos[0]] != ')':
                out.append(parse())
            pos[0] += 1
            return out
        if t == '#t':
            return True
        if t == '#f':
            return False
        if t == 'nil':
            return None
        try:
            return int(t)
        except ValueError:
            pass
        try:
            return float(t)
        except ValueError:
            pass
        return t

    budget = [fuel]

    def lookup(env, name):
        while env is not None:
            if name in env[0]:
                return env[0][name]
            env = env[1]
        raise KeyError(name)

    def ev(x, env):
        budget[0] -= 1
        if budget[0] < 0:
            raise RuntimeError('fuel')
        if x is True or x is False or x is None:
            return x
        if isinstance(x, (int, float)):
            return x
        if isinstance(x, str):
            return lookup(env, x)
        op = x[0]
        if op == 'if':
            c = ev(x[1], env)
            if c is not False and c is not None:
                return ev(x[2], env)
            if len(x) > 3:
                return ev(x[3], env)
            return None
        if op == 'define':
            env[0][x[1]] = ev(x[2], env)
            return env[0][x[1]]
        if op == 'lambda':
            return ['closure', x[1], x[2], env]
        if op == 'let':
            scope = [{}, env]
            for b in x[1]:
                scope[0][b[0]] = ev(b[1], env)
            return ev(x[2], scope)
        fn = ev(op, env)
        args = [ev(a, env) for a in x[1:]]
        if isinstance(fn, list):
            scope = [{}, fn[3]]
            for i in range(len(fn[1])):
                scope[0][fn[1][i]] = args[i]
            return ev(fn[2], scope)
        return fn(*args)

    def add(*a):
        t = 0
        for v in a:
            t += v
        return t

    def sub(*a):
        if len(a) == 1:
            return -a[0]
        t = a[0]
        for v in a[1:]:
            t -= v
        return t

    def mul(*a):
        t = 1
        for v in a:
            t *= v
        return t

    glob = [{'+': add, '-': sub, '*': mul, '<': lambda a, b: a < b, '>': lambda a, b: a > b, '=': lambda a, b: a == b}, None]
    try:
        forms = []
        while pos[0] < len(toks):
            forms.append(parse())
        result = None
        for f in forms:
            result = ev(f, glob)
        return result
    except RuntimeError as e:
        if str(e) == 'fuel':
            return 'out of fuel'
        return 'error'
    except Exception:
        return 'error'

