practice.solution:
def keep_newest(names, keep):
    groups = {}
    for n in names:
        kind = n.split('-')[2] if n.count('-') >= 3 else ''
        if kind not in groups:
            groups[kind] = []
        groups[kind].append(n)
    out = []
    for kind in groups:
        files = sorted(groups[kind])
        cut = len(files) - keep
        if cut > 0:
            out.extend(files[:cut])
    return sorted(out)
